file.content:
        _fail(_field_path(latest_path, "finished_at"), "terminal attempt is unfinished")


def _validate_capability_invariants(state: dict[str, Any]) -> None:
    attempt_ids: set[str] = set()
    for name, capability in state["batch"]["capabilities"].items():
        path = _field_path("batch.capabilities", name)
        attempts = capability["attempts"]
        status = capability["status"]
        if status == "pending" and attempts:
            _fail(_field_path(path, "attempts"), "pending capability has attempts")
        if status == "skipped":
            if capability["required"]:
                _fail(_field_path(path, "required"), "required capability cannot skip")
            if attempts:
                _fail(_field_path(path, "attempts"), "skipped capability has attempts")
        if status in {"running", "failed", "succeeded"} and not attempts:
            _fail(
                _field_path(path, "attempts"), f"{status} capability needs an attempt"
            )
        _validate_capability_attempts(attempts, path, attempt_ids)
        _validate_latest_capability(capability, path)


def _validate_batch_invariants(state: dict[str, Any]) -> None:
    batch = state["batch"]
    if batch["status"] != "idle" and not batch["id"]:
        _fail("batch.id", "non-idle batch requires an identifier")
    if batch["status"] == "completed":
        if batch["completed_at"] is None:
            _fail("batch.completed_at", "completed batch requires a timestamp")
        for name, capability in batch["capabilities"].items():
            if capability["required"] and capability["status"] != "succeeded":
                _fail(
                    _field_path(_field_path("batch.capabilities", name), "status"),
                    "required capability must succeed before completion",
                )


def validate_state(value: object) -> State:
    document = _require_dict(value, "state")
    if "schema_version" not in document:
        _fail("schema_version", "required field is missing")
    version = _require_integer(document["schema_version"], "schema_version")
    if version != SCHEMA_VERSION:
        _fail("schema_version", f"must equal {SCHEMA_VERSION}")
    _check_decoded_json_depth(document, source="state")
    try:
        encoded = (
            json.dumps(document, ensure_ascii=False, indent=2, sort_keys=True) + "\n"
        ).encode("utf-8")
    except (
        TypeError,
        ValueError,
        OverflowError,
        RecursionError,
        UnicodeEncodeError,
    ) as error:
        try:
            _validate_owned(document, State, "")

class ClaudeDriver:
    name = "claude"

    def __init__(self, settings: AgentSettings, *, run_id: str) -> None:
        options = settings.options
        if options.keys() - {
            "permission_mode",
            "allow_explicit_model",
            "fallback_model",
        }:
            raise ValueError("Unknown Claude driver option")
        if options.get("permission_mode") != "auto":
            raise ValueError("Claude permission_mode must be auto")
        if type(options.get("allow_explicit_model", False)) is not bool:
            raise ValueError("allow_explicit_model must be a boolean")
        if "fallback_model" in options and (
            not isinstance(options["fallback_model"], str)
            or not options["fallback_model"].strip()
        ):
            raise ValueError("fallback_model must be a nonblank string")
        defaults = {
            "CLAUDE_UNATTENDED": "1",
            "CLAUDE_CODE_PRINT_BG_WAIT_CEILING_MS": "0",
        }
        for key, value in settings.environment.items():
            if key in defaults and value != defaults[key]:
                raise ValueError(f"Cannot override fixed Claude environment key: {key}")
        self._settings = settings
        self._run_id = run_id
        self._environment = defaults | dict(settings.environment)
        self._session_id: str | None = None
        self._limit_live = False
        self._messages: OrderedDict[str, dict[str, int]] = OrderedDict()
        self._message_totals: dict[str, int] = {}
        # Evicted IDs remain in a fixed Bloom filter. False positives can
        # conservatively undercount new messages, but never inflate replays.
        self._evicted = bytearray(1024 * 1024)

    def default_prompt(self, phase: str) -> str:
        if phase not in {"build", "review", "done"}:
            raise ValueError(f"Unknown phase: {phase}")
        return "/autopilot:run-autopilot"

    def probe(self) -> DriverHealth:
        command = self._settings.command[0]
        resolved = shutil.which(command)
        if resolved is None:
            return DriverHealth(
                False, f"Command is missing or not executable: {command}"
            )
        return DriverHealth(
            True, f"Executable command: {resolved}; permission_mode=auto"
        )

    def build_launch(self, request: LaunchRequest) -> LaunchSpec:
        settings = self._settings
        model = request.model
        if model is None:
            raise ValueError("Claude requires a model tier")
        if model in settings.tiers:
            model = settings.tiers[model]
        elif not settings.options.get("allow_explicit_model", False):
            raise ValueError(f"Unknown Claude model tier: {model}")
        if request.effort is None or not request.effort.strip():
            raise ValueError("Claude requires a nonblank effort")
        fallback_arguments: tuple[str, ...] = ()
        fallback_tier = settings.options.get("fallback_model")
        if isinstance(fallback_tier, str):
            if fallback_tier not in settings.tiers:
                raise ValueError(f"Unknown Claude fallback tier: {fallback_tier}")
            fallback_model = settings.tiers[fallback_tier]
            if fallback_model != model:
                fallback_arguments = ("--fallback-model", fallback_model)
        return LaunchSpec(
            argv=(
                *settings.command,
                "-p",
                "--permission-mode",
                "auto",
                "--model",
                model,
                "--effort",
                request.effort,
                *fallback_arguments,
                "--output-format",
                "stream-json",
                "--verbose",
                request.prompt,
            ),
            env=dict(self._environment),
            cwd=request.root,
            raw_format="claude-stream-json-v1",
        )

    def decode(self, raw_line: str) -> tuple[Observation, ...]:

def _commit_operation(
    store: StateStore, operation: RecoveryOperation, *, verify: Callable[[], None]
) -> State:
    def commit(state: State) -> State:
        verify()
        current = state["recovery"]["operation"]
        if (
            current is None
            or current["id"] != operation["id"]
            or current["step"] != "recorded"
        ):
            raise RecoveryConflictError(
                f"recovery operation {operation['id']} changed before commit"
            )
        result = reset_prd_fields(state)
        if operation["kind"] == "park":
            parks = result["batch"]["parks_consecutive"] + 1
            result["batch"]["parks_consecutive"] = parks
            if parks >= 2:
                result["work"]["phase"] = "paused"
                result["work"]["next_phase"] = "paused"
                result["control"]["pause_reason"] = {
                    "site": "systemic_park",
                    "detail": (
                        f"{parks} consecutive PRDs parked via wrapper_died; "
                        "batch halted"
                    ),
                    "created_at": operation["created_at"],
                }
        else:
            result["batch"]["parks_consecutive"] = 0
        return result

    return store.transaction(commit, publication_guard=verify)


@dataclass(frozen=True)
class _Request:
    kind: RecoveryKind

"""Authoritative pure resume-target mapping for v1 state."""

from __future__ import annotations

from ovcaq.state.schema import State


def resume_target(state: State) -> str:
    """Describe the next action from committed v1 state only."""
    operation = state["recovery"]["operation"]
    if operation is not None:
        return f"reconcile {operation['kind']} {operation['id']} for {operation['prd']}"

    phase = state["work"]["phase"]
    if phase == "paused":
        pause_reason = state["control"]["pause_reason"]
        if pause_reason is not None and pause_reason["site"] == "review_cap":
            return (
                "cap-pause resume handler: present unresolved findings, "
                "branch resume/abandon"
            )
        return "paused: await user"

    if phase == "review":
        if "review" in state["work"]["completed_phases"]:
            return "skip review -> done"
        cycle = max(1, state["review"]["cycle"])
        return f"run review loop at cycle {cycle}"

    if phase == "build":
        tasks = state["tasks"]
        if tasks:
            pending = next(
                (task for task in tasks if task["status"] != "completed"),
                None,
            )
            if pending is None:
                return "all tasks done -> review gate"
            return f"continue build at first non-completed task {pending['id']}"
        if state["batch"]["catchup"]["completed_at"] is not None:
            return "skip catchup -> planning"
        return "build: catchup then planning"

    if phase == "done":
        return "done"
    return f"unknown phase: {phase}"

def load_metric_rows(path: Path) -> tuple[Mapping[str, object], ...]:
    """Load provider-neutral normalized metric rows from a JSONL ledger."""
    try:
        payload = _read_file(None, str(path))
        if payload is None:
            return ()
        text = payload.decode("utf-8")
    except (OSError, UnicodeDecodeError) as error:
        raise ReportError(f"cannot read metrics ledger {path}: {error}") from error

    rows: list[Mapping[str, object]] = []
    for line_number, line in enumerate(text.splitlines(), start=1):
        if not line.strip():
            continue
        source = f"{path}:{line_number}"
        try:
            value = decode_json(line, source=source)
            validate_json_value(value, source)
        except ValueError as error:
            raise ReportError(f"invalid metrics row at {source}: {error}") from error
        if not isinstance(value, dict):
            raise ReportError(f"invalid metrics row at {source}: expected object")
        rows.append(cast(Mapping[str, object], value))
    return tuple(rows)


def _metric_decimal(value: object) -> Decimal | None:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return None
    try:
        result = Decimal(str(value))
    except InvalidOperation:
        return None
    return result if result.is_finite() else None


def _metric_integer(value: object) -> int | None:
    if isinstance(value, bool) or not isinstance(value, int):
        return None
    return value


def _sum_decimal(rows: tuple[Mapping[str, object], ...], field: str) -> Decimal | None:
    total = Decimal(0)
    for row in rows:
        value = _metric_decimal(row.get(field))
        if value is None:
            return None
        total += value
    return total


def _sum_integer(rows: tuple[Mapping[str, object], ...], field: str) -> int | None:
    total = 0
    for row in rows:
        value = _metric_integer(row.get(field))
        if value is None:
            return None
        total += value
    return total


def _metric_partitions(
    metric_rows: Iterable[Mapping[str, object]],
) -> tuple[tuple[Mapping[str, object], ...], tuple[Mapping[str, object], ...]]:
    rows = tuple(
        {
            **row,
            "batch": row.get("batch_id"),
            "ts_start": row.get("started_at"),
            "wall_secs": row.get("wall_seconds"),
            "cost_usd": usage.get("cost_usd"),
            "tokens_out": usage.get("output_tokens"),
        }
        if "schema_version" in row
        else row
        for row in metric_rows
        for usage in [row.get("usage") or {}]
        if isinstance(usage, Mapping)
    )
    sessions = tuple(
        sorted(
            (row for row in rows if "phase_launched" in row),
            key=lambda row: (
                str(row.get("batch", "")),
                str(row.get("prd", "")),
                str(row.get("ts_start", "")),
                str(row.get("phase_launched", "")),
                json.dumps(dict(row), sort_keys=True, ensure_ascii=False),
            ),
        )
    )
    convergences = tuple(
        sorted(
            (row for row in rows if row.get("event") == "review_converged"),
            key=lambda row: (
                str(row.get("batch", "")),
                str(row.get("prd", "")),
                str(row.get("ts", "")),
                json.dumps(dict(row), sort_keys=True, ensure_ascii=False),
            ),
        )
    )
    return sessions, convergences


def _reduce_metric_partitions(
    sessions: tuple[Mapping[str, object], ...],
    convergences: tuple[Mapping[str, object], ...],
) -> MetricsSummary:
    return MetricsSummary(
        sessions=len(sessions),
        wall_secs=_sum_decimal(sessions, "wall_secs"),
        cost_usd=_sum_decimal(sessions, "cost_usd"),
        tokens_out=_sum_integer(sessions, "tokens_out"),
        review_convergences=len(convergences),
        cycles_to_converge=_sum_integer(convergences, "cycles_to_converge"),
    )


def reduce_metrics(
    metric_rows: Iterable[Mapping[str, object]],
) -> MetricsSummary:
    """Reduce normalized metrics; missing mixed-row totals remain unknown."""
    return _reduce_metric_partitions(*_metric_partitions(metric_rows))


def _metrics_for_batch(
    metric_rows: Iterable[Mapping[str, object]], batch_id: str
) -> tuple[Mapping[str, object], ...]:
    return tuple(
        row for row in metric_rows if row.get("batch_id", row.get("batch")) == batch_id
    )
